mapper.select:
SELECT id, profile_key, built_in, enabled, active_version, last_version, revision,
       created_at, updated_at, created_by, updated_by
FROM manga_agent_profile WHERE profile_key = #{key}

SELECT id, profile_key, built_in, enabled, active_version, last_version, revision,
       created_at, updated_at, created_by, updated_by
FROM manga_agent_profile ORDER BY id LIMIT #{limit}

SELECT id, profile_key, version_no, status, definition_json, definition_fingerprint,
       published_at, published_by, created_at, updated_at, created_by, updated_by
FROM manga_agent_profile_version WHERE profile_key = #{key} AND version_no = #{version}

SELECT id, profile_key, version_no, status, definition_fingerprint,
       published_at, published_by, created_at, updated_at, created_by, updated_by
FROM manga_agent_profile_version WHERE profile_key = #{key} ORDER BY version_no DESC LIMIT #{limit}

SELECT id, profile_key, version_no, action, previous_active_version, active_version,
       profile_revision, definition_fingerprint, comment, created_at, updated_at, created_by, updated_by
FROM manga_agent_profile_audit WHERE profile_key = #{key}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}
